LUMEN_TEST(rem_units) {
    // CSS Values 4 §6.1.1: 1rem is the root font size; with 16 px, 10rem = 160 px, 2.5rem =
    // 40 px. A row of 160 × 40 with a 2rem-basis item and a `flex-grow: 1` one: the first is
    // 32 px, the second takes 160 − 32 = 128 px; both stretch to 40 px.
    tree t{};
    t.nodes.push_back({parse_style("width:10rem;height:2.5rem"), {1, 2}, {}});
    t.nodes.push_back({parse_style("flex-basis:2rem"), {}, {}});
    t.nodes.push_back({parse_style("flex-grow:1"), {}, {}});
    layout_node(t, 0, 160.f, 40.f, std::numeric_limits<float>::quiet_NaN(),
                std::numeric_limits<float>::quiet_NaN());
    std::vector<lx::rect2f> rects;
    lx::layout::flex_input in{};
    const lx::layout::flex_output root = solve_node(t, 0, in, rects);
    LUMEN_CHECK(root.width == 160.f && root.height == 40.f);
    LUMEN_CHECK(t.nodes[1].layout.x == 0.f && t.nodes[1].layout.width == 32.f &&
                t.nodes[1].layout.height == 40.f);
    LUMEN_CHECK(t.nodes[2].layout.x == 32.f && t.nodes[2].layout.width == 128.f);
    // A different rem scales every rem length: 20 px → 10rem = 200, 2rem = 40.
    t.rem_px = 20.f;
    in.rem_px = 20.f;
    const lx::layout::flex_output scaled = solve_node(t, 0, in, rects);
    LUMEN_CHECK(scaled.width == 200.f && scaled.height == 50.f);
    LUMEN_CHECK(rects[0].width == 40.f && rects[1].width == 160.f);
    // The 32-bit length keeps the value: 30 bits, the float's two low mantissa bits gone.
    LUMEN_CHECK(lx::layout::rem(2.5f).value() == 2.5f &&
                lx::layout::rem(2.5f).kind() == lx::layout::unit::rem);
    LUMEN_CHECK(lx::layout::percent(33.25f).value() == 33.25f);
    LUMEN_CHECK(lx::layout::px(1234567.f).value() == 1234567.f);
    LUMEN_CHECK(sizeof(lx::layout::length) == 4);
}

LUMEN_TEST(overflow_scroll_content_size) {
    // Chrome, Taffy's flex_overflow_scroll_container_padding: a 300 × 200 scroll container
    // with 20 px vertical and 10 px horizontal padding over a 100 × 1000 child reports
    // scroll_height 855 with a 15 px scrollbar: content height 855 + (200 − 15) = 1040 =
    // 20 + 1000 + 20 (the end padding counts, CSS Overflow 3 §2.2), and scroll_width 0
    // (10 + 100 + 10 = 120 fits). Without a gutter the content box is the padding box
    // 300 × 200, so content_width is 300 and the scroll range is 1040 − 200 = 840.
    tree t{};
    t.nodes.push_back(
        {parse_style(
             "overflow-x:scroll;overflow-y:scroll;width:300px;height:200px;padding-top:20px;"
             "padding-left:10px;padding-bottom:20px;padding-right:10px"),
         {1},
         {}});
    t.nodes.push_back({parse_style("width:100px;height:1000px"), {}, {}});
    std::vector<lx::rect2f> rects;
    lx::layout::flex_input in{};
    in.known_width = 300.f;
    in.known_height = 200.f;
    const lx::layout::flex_output o = solve_node(t, 0, in, rects);
    LUMEN_CHECK(o.width == 300.f && o.height == 200.f);
    LUMEN_CHECK(o.content_height == 1040.f);
    LUMEN_CHECK(o.content_width == 300.f);
    // The child keeps its 1000 px: a scroll container's content may exceed its box.
    LUMEN_CHECK(rects[0].x == 10.f && rects[0].y == 20.f && rects[0].height == 1000.f);
}

LUMEN_TEST(solve_refuses_short_scratch) {
    tree t{};
    t.nodes.push_back({parse_style("width:10px"), {1, 2}, {}});
    t.nodes.push_back({{}, {}, {}});
    t.nodes.push_back({{}, {}, {}});
    tree_ctx ctx{&t, 0};
    lx::layout::flex_children ch{&ctx, 2, tree_style, tree_measure};
    lx::rect2f rects[2];
    lx::layout::flex_item_state items[1];
    lx::layout::flex_line_state lines[2];
    const auto r = lx::layout::solve_flex(t.nodes[0].style, {}, ch, rects, {items, lines});
    LUMEN_CHECK(!r.ok() && r.get_error().domain == lx::error_domain::invalid_argument);
}

// ── lx.ui: flex containers on ui_node ────────────────────────────────────────────

namespace {

/// A leaf whose content is `text`: 7 px a character, 14 px high (min-content: one
/// character; it wraps nowhere else). Counts nothing itself: `ui_layout_counters` does.
struct label_props {
    const char* text = "";
};

class label_leaf final : public lx::ui::ui_node {
public:
    [[nodiscard]] static lx::ui::element_type_id static_type() {
        static const lx::ui::element_type_id id = lx::ui::next_element_type_id();
        return id;
    }
    [[nodiscard]] lx::ui::element_type_id type() const override { return static_type(); }
    [[nodiscard]] const char* type_name() const override { return "label_leaf"; }

    bool apply(const label_props& p) {
        const bool changed = std::strcmp(p.text, text_) != 0;
        std::snprintf(text_, sizeof(text_), "%s", p.text);
        return changed;
    }

    [[nodiscard]] lx::size2i measure(lx::layout::constraints c,
                                     lx::ui::size_hint hint) const override {
        const int chars = static_cast<int>(std::strlen(text_));
        lx::size2i out{(hint == lx::ui::size_hint::min ? std::min(chars, 1) : chars) * 7, 14};
        out.width = std::clamp(out.width, c.min.width, std::max(c.min.width, c.max.width));
        out.height = std::clamp(out.height, c.min.height, std::max(c.min.height, c.max.height));
        return out;
    }

private:
    char text_[32] = "";
};

[[nodiscard]] lx::ui::child label(const char* text, lx::ui::element_key key = 0) {
    return lx::ui::describe<label_leaf, label_props>({text}, key);
}

[[nodiscard]] lx::layout::flex_style style(std::string_view css) {
    return parse_style(css);
}

/// Allocation counter (the replaced operator new below), as test_text_node and
/// lumen-ui-bench count them.
std::atomic<unsigned long long> g_allocations{0};

} // namespace

void* operator new(std::size_t n) {
    g_allocations.fetch_add(1, std::memory_order_relaxed);
    if (void* p = std::malloc(n ? n : 1))
        return p;
    throw std::bad_alloc{};
}
void* operator new[](std::size_t n) {
    g_allocations.fetch_add(1, std::memory_order_relaxed);
    if (void* p = std::malloc(n ? n : 1))
        return p;
    throw std::bad_alloc{};
}
void* operator new(std::size_t n, const std::nothrow_t&) noexcept {
    g_allocations.fetch_add(1, std::memory_order_relaxed);
    return std::malloc(n ? n : 1);
}
void* operator new[](std::size_t n, const std::nothrow_t&) noexcept {
    g_allocations.fetch_add(1, std::memory_order_relaxed);
    return std::malloc(n ? n : 1);
}
void operator delete(void* p) noexcept {
    std::free(p);
}
void operator delete[](void* p) noexcept {
    std::free(p);
}
void operator delete(void* p, std::size_t) noexcept {
    std::free(p);
}
void operator delete[](void* p, std::size_t) noexcept {
    std::free(p);
}

namespace {

/// Builds `describe` into a retained tree through `ui_root` and lays it out at `bounds`.
struct ui_harness {
    lx::runtime::memory_arena arena{256 * 1024};
    lx::ui::ui_root root{arena};
    lx::scene::draw_list draws{};

    ui_harness(lx::ui::describe_fn describe, lx::rect2i bounds) {
        lx::ui::ui_damage().clear();
        root.set_describer(describe);
        root.set_bounds(bounds);
        (void)root.tick(draws);
    }
    [[nodiscard]] lx::ui::ui_node& node(std::initializer_list<unsigned> path) const {
        lx::ui::ui_node* n = root.tree();
        for (unsigned i : path)
            n = n->child_at(i);
        return *n;
    }
};

[[nodiscard]] bool same(lx::rect2i a, lx::rect2i b) {
    return a.x == b.x && a.y == b.y && a.width == b.width && a.height == b.height;
}

lx::ui::child describe_grow_row(lx::ui::build_context&) {
    // A 300 px row: a 50 px item, a `grow(1)` item with 20 px of content, a 50 px item.
    lx::ui::child items[3] = {label("abcdefg") | lx::ui::pin_size({50, 14}),
                              label("abc") | lx::ui::grow(1),
                              label("abcdefg") | lx::ui::pin_size({50, 14})};
    return lx::ui::flex(style("align-items:flex-start;padding-left:5px;padding-top:5px"), items);
}

} // namespace

LUMEN_TEST(grow_decorator_flexes_in_a_flex_node) {
    // §9.7: inner width 300 − 5 = 295; bases 50 (the pinned size: min = max = 50), 21
    // (3 × 7, the grow item's content), 50; free 295 − 121 = 174 goes to the only item with
    // a grow factor: 21 + 174 = 195. Positions from the 5 px padding edge: 5, 55, 250.
    ui_harness h{describe_grow_row, {0, 0, 300, 40}};
    LUMEN_CHECK(same(h.node({0}).bounds(), {5, 5, 50, 14}));
    LUMEN_CHECK(same(h.node({1}).bounds(), {55, 5, 195, 14}));
    LUMEN_CHECK(same(h.node({2}).bounds(), {250, 5, 50, 14}));
    // The grow node passes its bounds to its content.
    LUMEN_CHECK(same(h.node({1, 0}).bounds(), {55, 5, 195, 14}));
    LUMEN_CHECK(static_cast<lx::ui::grow_node&>(h.node({1})).grow_factor() == 1u);
}

